examples.sparql:
PREFIX hf: <https://w3id.org/rete/huggingface#>
SELECT ?base (COUNT(*) AS ?finetunes) WHERE {
  ?model hf:finetunedFrom ?base .
}
GROUP BY ?base ORDER BY DESC(?finetunes) LIMIT 20

PREFIX hf: <https://w3id.org/rete/huggingface#>
SELECT (COUNT(DISTINCT ?descendant) AS ?lineage) WHERE {
  ?descendant (hf:finetunedFrom|hf:quantizedFrom|hf:adapterFor|hf:mergedFrom)+
              <https://huggingface.co/meta-llama/Llama-3.1-8B> .
}

PREFIX hf: <https://w3id.org/rete/huggingface#>
SELECT ?model (COUNT(?space) AS ?spaces) WHERE {
  ?space hf:usesModel ?model .
}
GROUP BY ?model ORDER BY DESC(?spaces) LIMIT 20

PREFIX hf: <https://w3id.org/rete/huggingface#>
PREFIX schema: <https://schema.org/>
SELECT ?person ?name ?followers WHERE {
  ?person hf:memberOf <https://huggingface.co/mistralai> ;
          hf:followerCount ?followers .
  OPTIONAL { ?person schema:name ?name }
}
ORDER BY DESC(?followers) LIMIT 25

PREFIX hf: <https://w3id.org/rete/huggingface#>
CONSTRUCT {
  <https://huggingface.co/meta-llama/Llama-3.1-8B> hf:finetunedFrom ?parent .
  ?child hf:finetunedFrom <https://huggingface.co/meta-llama/Llama-3.1-8B> .
  ?space hf:usesModel <https://huggingface.co/meta-llama/Llama-3.1-8B> .
} WHERE {
  { <https://huggingface.co/meta-llama/Llama-3.1-8B> hf:finetunedFrom ?parent }
  UNION
  { SELECT ?child WHERE { ?child hf:finetunedFrom <https://huggingface.co/meta-llama/Llama-3.1-8B> } LIMIT 25 }
  UNION
  { SELECT ?space WHERE { ?space hf:usesModel <https://huggingface.co/meta-llama/Llama-3.1-8B> } LIMIT 25 }
}

PREFIX hf: <https://w3id.org/rete/huggingface#>
SELECT ?task (COUNT(?model) AS ?models) WHERE {
  ?model hf:pipelineTag ?task .
}
GROUP BY ?task ORDER BY DESC(?models) LIMIT 25

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?title ?author ?file WHERE {
  ?r dcite:resourceType "software" ;
     dcite:title ?title ;
     dcite:hasPart ?file ;
     dcite:creator [ dcite:agentName ?author ] .
} LIMIT 40

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?type (COUNT(?r) AS ?n) WHERE {
  ?r dcite:resourceType ?type .
} GROUP BY ?type ORDER BY DESC(?n)

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?prefix (COUNT(?r) AS ?n) WHERE {
  ?r dcite:prefix ?prefix .
} GROUP BY ?prefix ORDER BY DESC(?n) LIMIT 20

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT ?title ?year ?subject WHERE {
  ?r dcite:resourceType "thesis" ;
     dcite:title ?title ;
     dcite:publicationYear ?year ;
     dcterms:subject ?subject .
} ORDER BY DESC(?year) LIMIT 40

PREFIX pb: <https://w3id.org/rete/proteinbase#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name ?author ?iptm ?structure WHERE {
  ?d a pb:Design ;
     rdfs:label ?name ;
     pb:boltz2Iptm ?iptm ;
     pb:structure ?structure ;
     pb:author [ rdfs:label ?author ] .
}
ORDER BY DESC(?iptm)
LIMIT 25

PREFIX pb: <https://w3id.org/rete/proteinbase#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name ?strength ?target WHERE {
  ?e a pb:Evaluation ;
     pb:metric "binding_strength" ;
     pb:evaluationType "experimental" ;
     pb:valueLabel ?strength ;
     pb:ofDesign ?d ;
     pb:target [ rdfs:label ?target ] .
  ?d rdfs:label ?name .
}
LIMIT 50

PREFIX ethz: <https://w3id.org/rete/ethz#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT ?t ?title ?y WHERE {
  ?t a ethz:DoctoralThesis ; rdfs:label ?title ; dcterms:issued ?y .
} ORDER BY DESC(?y) LIMIT 50

PREFIX ethz: <https://w3id.org/rete/ethz#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name (COUNT(?w) AS ?n) WHERE {
  ?w ethz:creator ?a . ?a ethz:orcid ?o ; rdfs:label ?name .
} GROUP BY ?a ?name ORDER BY DESC(?n) LIMIT 25

PREFIX ethz: <https://w3id.org/rete/ethz#>
SELECT ?avail (COUNT(?w) AS ?n) WHERE {
  ?w ethz:availability ?avail .
} GROUP BY ?avail ORDER BY DESC(?n)

PREFIX su: <https://w3id.org/rete/swissubase#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?dataset ?title (COUNT(?v) AS ?versions) WHERE {
  ?dataset a su:Dataset ; dct:title ?title ; su:hasVersion ?v .
} GROUP BY ?dataset ?title ORDER BY DESC(?versions) LIMIT 15

PREFIX su: <https://w3id.org/rete/swissubase#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?version ?title ?license WHERE {
  ?version a su:DatasetVersion ; dct:title ?title ; dct:license ?license .
} LIMIT 50

PREFIX su: <https://w3id.org/rete/swissubase#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?study ?dataset ?datasetTitle WHERE {
  ?study a su:Study ; su:hasDataset ?dataset .
  ?dataset dct:title ?datasetTitle .
} LIMIT 50

PREFIX su: <https://w3id.org/rete/swissubase#>
SELECT ?licenceType (COUNT(?v) AS ?n) WHERE {
  ?v a su:DatasetVersion ; su:licenseIconCode ?licenceType .
} GROUP BY ?licenceType ORDER BY DESC(?n)

PREFIX su: <https://w3id.org/rete/swissubase#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?version ?title WHERE {
  ?version a su:DatasetVersion ; dct:title ?title ; su:hasDomainMetadata ?dm .
  ?dm su:consentOfRespondents true .
} LIMIT 50

PREFIX scholar: <https://w3id.org/rete/scholar#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?work ?doi ?title WHERE {
  ?work scholar:doi ?doi ; dct:title ?title .
} LIMIT 50

PREFIX neuro: <https://w3id.org/rete/neuro#>
PREFIX schema: <https://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?model ?astrocyte ?faces ?endfeet WHERE {
  ?c a neuro:Astrocyte ; rdfs:label ?astrocyte ;
     schema:contentUrl ?model ; neuro:faces ?faces ; neuro:endfeet ?endfeet .
} ORDER BY DESC(?faces)

PREFIX neuro: <https://w3id.org/rete/neuro#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?neuron ?type ?className ?def ?region WHERE {
  ?c a neuro:Neuron ; rdfs:label ?neuron ; neuro:cellType ?ct .
  ?ct rdfs:label ?type ; skos:broader ?cls .
  ?cls rdfs:label ?className ; skos:definition ?def .
  OPTIONAL { ?c neuro:brainRegion ?region }
} ORDER BY ?className LIMIT 30

PREFIX neuro: <https://w3id.org/rete/neuro#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?pre ?post ?w ?x ?y ?z WHERE {
  ?s a neuro:Synapse ; neuro:presynaptic/rdfs:label ?pre ; neuro:postsynaptic/rdfs:label ?post ;
     neuro:weight ?w ; neuro:locX ?x ; neuro:locY ?y ; neuro:locZ ?z .
} ORDER BY DESC(?w)

PREFIX neuro: <https://w3id.org/rete/neuro#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?nt (COUNT(?n) AS ?neurons) WHERE {
  ?n a neuro:Neuron ; neuro:neurotransmitter/rdfs:label ?nt .
} GROUP BY ?nt ORDER BY DESC(?neurons)

PREFIX neuro: <https://w3id.org/rete/neuro#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT { ?a neuro:connectsTo ?b . ?a rdfs:label ?la . ?b rdfs:label ?lb }
WHERE {
  ?a neuro:connectsTo ?b . ?a rdfs:label ?la . ?b rdfs:label ?lb .
} LIMIT 200

PREFIX schema: <http://schema.org/>
PREFIX imag: <https://imaging-plaza.epfl.ch/ontology#>
SELECT ?fair (COUNT(DISTINCT ?s) AS ?software) WHERE {
  ?s a schema:SoftwareSourceCode ; imag:fairLevel ?fair .
} GROUP BY ?fair ORDER BY ?fair

PREFIX schema: <http://schema.org/>
PREFIX imag: <https://imaging-plaza.epfl.ch/ontology#>
SELECT ?image ?name ?fair ?description WHERE {
  ?s a schema:SoftwareSourceCode ; schema:name ?name ; schema:description ?description ;
     imag:fairLevel ?fair ; schema:image ?img .
  ?img schema:contentUrl ?image .
} ORDER BY ?name LIMIT 60

PREFIX schema: <http://schema.org/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?author ?orcid (COUNT(DISTINCT ?s) AS ?software) WHERE {
  ?s a schema:SoftwareSourceCode ; schema:author ?p .
  ?p schema:name ?author .
  OPTIONAL { ?p owl:sameAs ?orcid }
} GROUP BY ?author ?orcid ORDER BY DESC(?software) ?author LIMIT 40

PREFIX schema: <http://schema.org/>
PREFIX imag: <https://imaging-plaza.epfl.ch/ontology#>
SELECT ?name ?kind ?title ?url WHERE {
  ?s a schema:SoftwareSourceCode ; schema:name ?name .
  { ?s imag:runnableExample ?e . ?e schema:url ?url ; schema:name ?title ; imag:hostType ?kind }
  UNION
  { ?s imag:hasExecutableNotebook ?e . ?e schema:url ?url ; schema:name ?title . BIND("notebook" AS ?kind) }
} ORDER BY ?name LIMIT 60

PREFIX schema: <http://schema.org/>
PREFIX imag: <https://imaging-plaza.epfl.ch/ontology#>
SELECT ?modality (COUNT(DISTINCT ?s) AS ?software) WHERE {
  ?s a schema:SoftwareSourceCode .
  { ?s imag:imagingModality ?modality }
  UNION
  { ?s schema:supportingData ?d . ?d imag:imagingModality ?modality }
} GROUP BY ?modality ORDER BY DESC(?software)

PREFIX schema: <http://schema.org/>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT ?name ?doi ?license WHERE {
  ?s a schema:SoftwareSourceCode ; schema:name ?name ; dcterms:references ?doi .
  OPTIONAL { ?s dcterms:license ?license }
} ORDER BY ?name LIMIT 80

PREFIX schema: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?s schema:author ?p . ?s rdfs:label ?name . ?p rdfs:label ?author .
}
WHERE {
  ?s a schema:SoftwareSourceCode ; schema:name ?name ; schema:author ?p .
  ?p schema:name ?author .
} LIMIT 300

shacl_shapes.shape:
@prefix sh:     <http://www.w3.org/ns/shacl#> .
@prefix schema: <http://schema.org/> .
@prefix sd:     <https://w3id.org/okn/o/sd#> .
@prefix imag:   <https://imaging-plaza.epfl.ch/ontology#> .
@prefix xsd:    <http://www.w3.org/2001/XMLSchema#> .

# The rungs of the Imaging Plaza FAIR ladder, as the platform itself scores them:
# each constraint's message names the level it gates, so every violation reads
# "this is what the project still has to add".
imag:FairLadderShape a sh:NodeShape ;
    sh:targetClass schema:SoftwareSourceCode ;

    # --- level 1-2: it must be findable and described at all
    sh:property [ sh:path schema:name        ; sh:minCount 1 ; sh:message "Fair level 1" ] ;
    sh:property [ sh:path schema:description ; sh:minCount 1 ; sh:message "Fair level 1" ] ;
    sh:property [ sh:path schema:codeRepository ; sh:minCount 1 ; sh:message "Fair level 1" ] ;
    sh:property [ sh:path schema:license     ; sh:minCount 1 ; sh:message "Fair level 2" ] ;
    sh:property [ sh:path schema:author      ; sh:minCount 1 ; sh:message "Fair level 2" ] ;

    # --- level 3: reusable by someone else
    sh:property [ sh:path sd:readme            ; sh:minCount 1 ; sh:message "Fair level 3" ] ;
    sh:property [ sh:path schema:programmingLanguage ; sh:minCount 1 ; sh:message "Fair level 3" ] ;

    # --- level 4-5: runnable, and reproducibly so
    sh:property [ sh:path sd:hasDocumentation        ; sh:minCount 1 ; sh:message "Fair level 4" ] ;
    sh:property [ sh:path sd:hasExecutableInstructions ; sh:minCount 1 ; sh:message "Fair level 5" ] ;
    sh:property [ sh:path sd:hasSoftwareImage        ; sh:minCount 1 ; sh:message "Fair level 5" ] ;

    # --- typing the source actually gets wrong: date-times where dates are declared
    sh:property [ sh:path schema:dateCreated ; sh:datatype xsd:date ;
                  sh:message "dateCreated must be an xsd:date" ] .

examples.sparql:
PREFIX c4dt: <https://w3id.org/rete/c4dt#>
PREFIX schema: <http://schema.org/>
SELECT ?lab ?code ?prof (COUNT(DISTINCT ?p) AS ?projects) (COUNT(DISTINCT ?repo) AS ?repos) WHERE {
  ?l a c4dt:Lab ; schema:name ?lab ; c4dt:labIdentifier ?code ;
     c4dt:headOfLab ?person .
  ?person schema:name ?prof .
  ?p c4dt:developedBy ?l .
  OPTIONAL { ?p schema:codeRepository ?repo }
} GROUP BY ?lab ?code ?prof ORDER BY DESC(?projects)

PREFIX c4dt: <https://w3id.org/rete/c4dt#>
PREFIX schema: <http://schema.org/>
SELECT ?title ?lab ?layman WHERE {
  ?p c4dt:category <https://w3id.org/rete/c4dt/category/Privacy> ;
     c4dt:applicationDomain <https://w3id.org/rete/c4dt/application/Health> ;
     schema:name ?title ; c4dt:laymanDescription ?layman ;
     c4dt:developedBy ?l .
  ?l schema:name ?lab .
}

PREFIX c4dt: <https://w3id.org/rete/c4dt#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?language (COUNT(DISTINCT ?p) AS ?projects) (COUNT(DISTINCT ?l) AS ?labs) WHERE {
  ?p c4dt:programmingLanguage ?c ; c4dt:developedBy ?l .
  ?c skos:prefLabel ?language .
} GROUP BY ?language ORDER BY DESC(?projects)

PREFIX c4dt: <https://w3id.org/rete/c4dt#>
PREFIX schema: <http://schema.org/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?title ?status ?work ?product ?kind WHERE {
  ?p c4dt:incubation ?i ; schema:name ?title .
  ?i c4dt:incubationStatus/skos:prefLabel ?status ;
     c4dt:incubationWork ?work .
  OPTIONAL {
    ?i c4dt:hasProduct ?prod .
    ?prod schema:name ?product ; c4dt:productType/skos:prefLabel ?kind .
  }
} ORDER BY ?status ?title

PREFIX c4dt: <https://w3id.org/rete/c4dt#>
PREFIX schema: <http://schema.org/>
SELECT ?paper ?project ?lab ?url WHERE {
  ?p schema:citation ?a ; schema:name ?project ; c4dt:developedBy ?l .
  ?a a schema:ScholarlyArticle ; schema:name ?paper .
  ?l schema:name ?lab .
  OPTIONAL { ?a schema:url ?url }
} ORDER BY ?lab LIMIT 200

PREFIX c4dt: <https://w3id.org/rete/c4dt#>
PREFIX schema: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?l c4dt:develops ?p . ?p schema:codeRepository ?repo .
  ?l rdfs:label ?lab . ?p rdfs:label ?title . ?repo rdfs:label ?handle .
}
WHERE {
  ?p c4dt:developedBy ?l ; schema:name ?title ; schema:codeRepository ?repo .
  ?l schema:name ?lab .
  ?repo <https://open-pulse.epfl.ch/ontology#githubRepositoryHandle> ?handle .
} LIMIT 250

shacl_shapes.shape:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix schema: <http://schema.org/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix c4dt: <https://w3id.org/rete/c4dt#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

c4dt:SoftwareSourceCodeShape a sh:NodeShape ;
    sh:targetClass schema:SoftwareSourceCode ;
    sh:property [
        sh:path schema:name ;
        sh:nodeKind sh:Literal ;
        sh:minCount 1 ;
    ] ;
    sh:property [
        sh:path rdfs:label ;
        sh:nodeKind sh:Literal ;
        sh:minCount 1 ;
    ] ;
    sh:property [
        sh:path c4dt:tag ;
        sh:class skos:Concept ;
    ] ;
    sh:property [
        sh:path c4dt:category ;
        sh:class c4dt:Category ;
    ] ;
    sh:property [
        sh:path c4dt:applicationDomain ;
        sh:class c4dt:ApplicationDomain ;
    ] ;
    sh:property [
        sh:path c4dt:projectType ;
        sh:class c4dt:ProjectType ;
    ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix schema: <http://schema.org/> .
@prefix c4dt: <https://w3id.org/rete/c4dt#> .
@prefix openpulse: <https://open-pulse.epfl.ch/ontology#> .

c4dt:SoftwareProjectShape a sh:NodeShape ;
    sh:targetClass c4dt:SoftwareProject ;
    sh:property [
        sh:path c4dt:developedBy ;
        sh:class schema:Organization ;
        sh:minCount 1 ;
    ] ;
    sh:property [
        sh:path openpulse:discipline ;
        sh:class openpulse:DisciplineEnumeration ;
        sh:minCount 1 ;
    ] ;
    sh:property [
        sh:path c4dt:dateAdded ;
        sh:nodeKind sh:Literal ;
        sh:minCount 1 ;
    ] ;
    sh:property [
        sh:path c4dt:laymanDescription ;
        sh:nodeKind sh:Literal ;
        sh:minCount 1 ;
    ] ;
    sh:property [
        sh:path c4dt:technicalDescription ;
        sh:nodeKind sh:Literal ;
        sh:minCount 1 ;
    ] ;
    sh:property [
        sh:path c4dt:slug ;
        sh:nodeKind sh:Literal ;
        sh:minCount 1 ;
    ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix schema: <http://schema.org/> .
@prefix c4dt: <https://w3id.org/rete/c4dt#> .

c4dt:OrganizationDevelopsShape a sh:NodeShape ;
    sh:targetClass schema:Organization ;
    sh:property [
        sh:path c4dt:develops ;
        sh:class schema:SoftwareSourceCode ;
    ] .

examples.sparql:
PREFIX enac: <https://w3id.org/rete/enac-it4research#>
PREFIX schema: <http://schema.org/>
SELECT ?what (COUNT(DISTINCT ?x) AS ?n) WHERE {
  { ?x a enac:Project . BIND("Showcase projects" AS ?what) }
  UNION { ?x a enac:ResearchSoftware . BIND("Research software" AS ?what) }
  UNION { ?x a enac:StudentProject . BIND("Student project offers" AS ?what) }
  UNION { ?x a enac:Laboratory . BIND("Laboratories" AS ?what) }
  UNION { ?y enac:hasRepository ?x . BIND("Code repositories" AS ?what) }
  UNION { ?y enac:hasCodeOrganization ?x . BIND("GitHub/GitLab orgs" AS ?what) }
  UNION { ?x a schema:Dataset . BIND("Datasets" AS ?what) }
  UNION { ?x a schema:Person . BIND("People" AS ?what) }
  UNION { ?x a schema:ScholarlyArticle . BIND("Cited publications" AS ?what) }
}
GROUP BY ?what
ORDER BY DESC(?n)

PREFIX enac: <https://w3id.org/rete/enac-it4research#>
PREFIX schema: <http://schema.org/>
SELECT ?labCode ?software ?repo WHERE {
  ?sw a enac:ResearchSoftware ;
      schema:name ?software ;
      enac:developedBy ?unit ;
      enac:hasRepository ?repo .
  ?unit enac:unitCode ?labCode .
}
ORDER BY ?labCode ?software

PREFIX enac: <https://w3id.org/rete/enac-it4research#>
PREFIX schema: <http://schema.org/>
SELECT ?work ?dataset ?doi WHERE {
  ?w enac:releasesDataset ?dataset ;
     schema:name ?work .
  OPTIONAL { ?dataset schema:identifier ?doi }
}
ORDER BY ?work

PREFIX enac: <https://w3id.org/rete/enac-it4research#>
PREFIX schema: <http://schema.org/>
SELECT ?project ?contribution WHERE {
  ?p a enac:IT4ResearchProject ;
     schema:name ?project ;
     enac:it4rContribution ?contribution .
}
ORDER BY ?project

PREFIX enac: <https://w3id.org/rete/enac-it4research#>
PREFIX schema: <http://schema.org/>
SELECT ?project ?lab ?method ?conf ?evidence WHERE {
  ?i a enac:LabInference ;
     enac:aboutProject ?p ;
     enac:inferredUnit ?u ;
     enac:inferenceMethod ?method ;
     enac:inferenceConfidence ?conf ;
     enac:evidence ?evidence .
  ?p schema:name ?project .
  ?u enac:unitCode ?lab .
}
ORDER BY ?conf ?project

PREFIX enac: <https://w3id.org/rete/enac-it4research#>
PREFIX schema: <http://schema.org/>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?title ?journal ?year ?lab ?pdf WHERE {
  ?pub a schema:ScholarlyArticle ;
       schema:headline ?title ;
       enac:developedBy ?u .
  ?u enac:unitCode ?lab .
  OPTIONAL { ?pub dct:isPartOf ?journal }
  OPTIONAL { ?pub schema:datePublished ?year }
  OPTIONAL { ?pub enac:openAccessPdf ?pdf }
}
ORDER BY ?year

