enac:OpenDataProjectShape a sh:NodeShape ;
  sh:targetClass enac:OpenDataProject ;
  sh:property [ sh:path enac:category ; sh:class enac:Category ; sh:minCount 1 ] .

examples.sparql:
PREFIX lo: <https://w3id.org/rete/lombardi/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <https://schema.org/>
SELECT ?img ?drawing ?date ?medium ?dimensions ?accession WHERE {
  ?w lo:momaImage ?img ; lo:accession ?accession ; rdfs:label ?drawing .
  OPTIONAL { ?w schema:dateCreated ?date }
  OPTIONAL { ?w schema:artMedium ?medium }
  OPTIONAL { ?w lo:dimensions ?dimensions }
} ORDER BY ?drawing

PREFIX lo: <https://w3id.org/rete/lombardi/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?drawing ?from ?to ?actors ?arcs WHERE {
  ?w a lo:Drawing ; rdfs:label ?drawing ;
     lo:nodeCount ?actors ; lo:edgeCount ?arcs .
  OPTIONAL { ?w lo:narrationStart ?from . ?w lo:narrationEnd ?to }
} ORDER BY DESC(?arcs)

PREFIX lo: <https://w3id.org/rete/lombardi/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?arcType ?drawnAs (COUNT(?arc) AS ?arcs) WHERE {
  ?arc a lo:Arc ; lo:arcType ?t .
  ?t rdfs:label ?arcType ; lo:drawnAs ?drawnAs .
} GROUP BY ?arcType ?drawnAs ORDER BY DESC(?arcs)

PREFIX lo: <https://w3id.org/rete/lombardi/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?amount ?from ?to ?drawnAs ?drawing WHERE {
  ?e lo:amount ?amount ; lo:source ?s ; lo:target ?o ;
     lo:arcType ?t ; lo:inDrawing ?w .
  ?s rdfs:label ?from .
  ?o rdfs:label ?to .
  ?t lo:drawnAs ?drawnAs .
  ?w rdfs:label ?drawing .
} ORDER BY ?drawing

PREFIX lo: <https://w3id.org/rete/lombardi/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?drawingA ?drawingB ?sharedActors ?jaccard WHERE {
  ?o a lo:Overlap ; lo:sharedActorCount ?sharedActors ; lo:jaccard ?jaccard ;
     lo:betweenDrawing ?wa , ?wb .
  ?wa rdfs:label ?drawingA .
  ?wb rdfs:label ?drawingB .
  FILTER(STR(?drawingA) < STR(?drawingB))
} ORDER BY DESC(?sharedActors) LIMIT 40

PREFIX lo: <https://w3id.org/rete/lombardi/>
PREFIX lom: <http://www.lombardinetworks.net/lombardi.owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?outcome ?drawing ?narrationEnd WHERE {
  ?f a lom:FinalInfo ; rdfs:label ?outcome ; lo:appearsIn ?w .
  ?w rdfs:label ?drawing .
  OPTIONAL { ?w lo:narrationEnd ?narrationEnd }
} ORDER BY ?outcome

PREFIX lo: <https://w3id.org/rete/lombardi/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT { ?s ?rel ?o . ?s rdfs:label ?sn . ?o rdfs:label ?on }
WHERE {
  ?w rdfs:label "Nugan Hand Bank Sydney, Australia c. 1974-80, 1995"@en .
  ?e lo:inDrawing ?w ; lo:source ?s ; lo:target ?o ; lo:arcType ?t .
  BIND(IRI(CONCAT("https://w3id.org/rete/lombardi/rel/",
       LCASE(SUBSTR(STRAFTER(STR(?t), "#"), 1, 1)),
       SUBSTR(STRAFTER(STR(?t), "#"), 2))) AS ?rel)
  OPTIONAL { ?s rdfs:label ?sn }
  OPTIONAL { ?o rdfs:label ?on }
} LIMIT 200

