examples.sparql:
PREFIX geo: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX gsp: <http://www.opengis.net/ont/geosparql#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
PREFIX edm: <http://www.europeana.eu/schemas/edm/>
SELECT ?wkt ?title ?year ?author ?img ?man WHERE {
  ?m geo:lat ?lat ; geo:long ?long ; gsp:asWKT ?wkt ; dct:title ?title .
  OPTIONAL { ?m drm:year ?year }
  OPTIONAL { ?m dct:creator ?author }
  OPTIONAL { ?m drm:avif4k ?img }
  OPTIONAL { ?m drm:iiifManifest ?man }
  FILTER(?lat > 46.0 && ?lat < 46.9 && ?long > 6.0 && ?long < 7.2)
}
ORDER BY ?year LIMIT 200

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
SELECT ?img ?title ?year ?w ?h ?jp2 ?man WHERE {
  ?m drm:pixelWidth ?w ; drm:pixelHeight ?h ; dct:title ?title ;
     drm:jp2Master ?jp2 ; drm:iiifManifest ?man ; drm:avif4k ?img .
  OPTIONAL { ?m drm:year ?year }
  FILTER(?w > 60000)
}
ORDER BY DESC(?w) LIMIT 40

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
SELECT ?title ?date ?author ?claimed (COUNT(?m) AS ?n) WHERE {
  ?m dct:isPartOf ?pub .
  ?pub dct:title ?title .
  OPTIONAL { ?pub dct:date ?date }
  OPTIONAL { ?pub dct:creator ?author }
  OPTIONAL { ?pub drm:mapCount ?claimed }
} GROUP BY ?title ?date ?author ?claimed
ORDER BY DESC(?n) LIMIT 25

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
PREFIX edm: <http://www.europeana.eu/schemas/edm/>
SELECT ?img ?title ?year ?author ?wcm ?hcm ?man WHERE {
  ?m a drm:WallMap ; dct:title ?title ; drm:objWidthCm ?wcm ; drm:objHeightCm ?hcm .
  OPTIONAL { ?m drm:year ?year }
  OPTIONAL { ?m dct:creator ?author }
  OPTIONAL { ?m drm:avif4k ?img }
  OPTIONAL { ?m drm:iiifManifest ?man }
  FILTER(?wcm > 200)
}
ORDER BY DESC(?wcm) LIMIT 40

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
PREFIX edm: <http://www.europeana.eu/schemas/edm/>
SELECT ?img ?title ?year ?author ?wcm ?hcm ?man WHERE {
  ?m a drm:CelestialMap ; dct:title ?title ; drm:avif4k ?img .
  OPTIONAL { ?m drm:year ?year }
  OPTIONAL { ?m dct:creator ?author }
  OPTIONAL { ?m drm:objWidthCm ?wcm }
  OPTIONAL { ?m drm:objHeightCm ?hcm }
  OPTIONAL { ?m drm:iiifManifest ?man }
}
ORDER BY ?year LIMIT 60

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
SELECT ?img ?title ?year ?iiifRender ?man ?mirror WHERE {
  ?m a drm:Globe ; dct:title ?title ; drm:iiifManifest ?man ;
     drm:iiifManifestMirror ?mirror ; drm:iiifImage ?iiif ; drm:avif4k ?img .
  OPTIONAL { ?m drm:year ?year }
  BIND(IRI(CONCAT(STR(?iiif), "/full/!800,800/0/default.jpg")) AS ?iiifRender)
}
ORDER BY ?year LIMIT 40

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
PREFIX edm: <http://www.europeana.eu/schemas/edm/>
SELECT ?thumb ?title ?avif ?mirror ?man ?jp2 WHERE {
  ?m a drm:WallMap ; dct:title ?title ;
     drm:avif4k ?avif ; drm:iiifManifestMirror ?mirror ;
     drm:iiifManifest ?man ; drm:jp2Master ?jp2 ; edm:preview ?thumb .
}
LIMIT 30

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX drm: <https://w3id.org/rete/davidrumsey#>
PREFIX edm: <http://www.europeana.eu/schemas/edm/>
SELECT ?img ?title ?year
       (GROUP_CONCAT(DISTINCT ?place; separator=" · ") AS ?matched)
       (GROUP_CONCAT(DISTINCT ?city; separator=" · ") AS ?cities)
       (GROUP_CONCAT(DISTINCT ?county; separator=" · ") AS ?counties)
       (GROUP_CONCAT(DISTINCT ?state; separator=" · ") AS ?states)
       (GROUP_CONCAT(DISTINCT ?region; separator=" · ") AS ?regions)
       (GROUP_CONCAT(DISTINCT ?country; separator=" · ") AS ?countries)
       (GROUP_CONCAT(DISTINCT ?world; separator=" · ") AS ?worlds)
WHERE {
  ?m dct:spatial ?place ; dct:title ?title .
  OPTIONAL { ?m drm:city ?city }
  OPTIONAL { ?m drm:county ?county }
  OPTIONAL { ?m drm:stateProvince ?state }
  OPTIONAL { ?m drm:region ?region }
  OPTIONAL { ?m drm:country ?country }
  OPTIONAL { ?m drm:worldArea ?world }
  OPTIONAL { ?m drm:year ?year }
  OPTIONAL { ?m drm:avif4k ?img }
  FILTER(CONTAINS(STR(?place), "Japan"))
}
GROUP BY ?m ?img ?title ?year
ORDER BY ?year
LIMIT 50

PREFIX fmc: <https://w3id.org/rete/farmacos#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?medicamento ?sustancia ?efecto ?recomendacion WHERE {
  ?i a fmc:Interaccion ;
     fmc:gravedad <https://w3id.org/rete/farmacos/gravedad/contraindicada> ;
     fmc:medicamento ?m ; fmc:sustanciaObjetivo ?sustancia ;
     fmc:efecto ?efecto ; fmc:recomendacion ?recomendacion .
  ?m rdfs:label ?medicamento .
} LIMIT 100

PREFIX fmc: <https://w3id.org/rete/farmacos#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?excipiente (COUNT(DISTINCT ?m) AS ?medicamentos) WHERE {
  ?pr a fmc:Presentacion ; fmc:medicamento ?m ; fmc:excipiente ?e .
  ?e skos:prefLabel ?excipiente .
} GROUP BY ?excipiente ORDER BY DESC(?medicamentos) LIMIT 50

PREFIX fmc: <https://w3id.org/rete/farmacos#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?medicamento ?presentacion ?motivo ?desde WHERE {
  ?ps a fmc:ProblemaSuministro ; fmc:activo true ;
      rdfs:label ?presentacion ; fmc:observaciones ?motivo ;
      fmc:fechaInicio ?desde ; fmc:presentacion ?pr .
  ?pr fmc:medicamento ?m . ?m rdfs:label ?medicamento .
} ORDER BY DESC(?desde) LIMIT 100

PREFIX fmc: <https://w3id.org/rete/farmacos#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?medicamento ?prospecto ?prospectoPdf ?fichaTecnica WHERE {
  ?m a fmc:Medicamento ; rdfs:label ?medicamento ;
     fmc:urlProspecto ?prospecto ; fmc:urlProspectoPdf ?prospectoPdf ;
     fmc:urlFichaTecnica ?fichaTecnica .
} LIMIT 100

