examples.sparql:
SELECT ?class (COUNT(*) AS ?n) WHERE {
  ?s a ?class .
} GROUP BY ?class ORDER BY DESC(?n)

PREFIX schema: <http://schema.org/>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
PREFIX gme: <https://openpulse.science/git-metadata-extractor#>
SELECT ?name ?stars ?language WHERE {
  ?repo a schema:SoftwareSourceCode ;
        schema:name ?name ;
        pulse:githubRepoStars ?stars .
  OPTIONAL { ?repo gme:primary_language ?language }
} ORDER BY DESC(?stars) LIMIT 50

PREFIX schema: <http://schema.org/>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
SELECT ?person ?commits WHERE {
  ?c a pulse:Contribution ;
     pulse:contributionTo <https://github.com/AdaptiveMotorControlLab/CEBRA> ;
     schema:author ?person ;
     pulse:contributionCount ?commits .
} ORDER BY DESC(?commits)

PREFIX schema: <http://schema.org/>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
PREFIX org: <http://www.w3.org/ns/org#>
PREFIX gme: <https://openpulse.science/git-metadata-extractor#>
SELECT ?repo ?name (SAMPLE(?ln) AS ?lab) (SAMPLE(?st) AS ?stars) (SAMPLE(?lg) AS ?language) WHERE {
  ?repo a schema:SoftwareSourceCode ; schema:name ?name ; pulse:ownedBy ?o .
  ?o org:unitOf <https://ror.org/02s376052> .
  OPTIONAL { ?o schema:name ?ln }
  OPTIONAL { ?repo pulse:githubRepoStars ?st }
  OPTIONAL { ?repo gme:primary_language ?lg }
} GROUP BY ?repo ?name ORDER BY DESC(?stars) LIMIT 50

PREFIX schema: <http://schema.org/>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
PREFIX org: <http://www.w3.org/ns/org#>
SELECT ?fork ?name ?forkStars ?epflOriginal WHERE {
  ?epflOriginal a schema:SoftwareSourceCode ; pulse:ownedBy ?o .
  ?o org:unitOf <https://ror.org/02s376052> .
  ?fork pulse:isForkOf ?epflOriginal ; schema:name ?name .
  OPTIONAL { ?fork pulse:githubRepoStars ?forkStars }
} ORDER BY DESC(?forkStars) LIMIT 50

PREFIX schema: <http://schema.org/>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
PREFIX org: <http://www.w3.org/ns/org#>
SELECT ?org (SAMPLE(?ln) AS ?lab) (COUNT(DISTINCT ?repo) AS ?repos) (SUM(?st) AS ?totalStars) WHERE {
  ?repo a schema:SoftwareSourceCode ; pulse:ownedBy ?org .
  ?org org:unitOf <https://ror.org/02s376052> .
  OPTIONAL { ?org schema:name ?ln }
  OPTIONAL { ?repo pulse:githubRepoStars ?st }
} GROUP BY ?org ORDER BY DESC(?totalStars) LIMIT 40

PREFIX schema: <http://schema.org/>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
PREFIX org: <http://www.w3.org/ns/org#>
SELECT ?person (SAMPLE(?nm) AS ?name) (SAMPLE(?orc) AS ?orcid) (COUNT(DISTINCT ?repo) AS ?repos) WHERE {
  ?person org:hasMembership ?m . ?m org:organization <https://ror.org/02s376052> .
  OPTIONAL { ?person schema:name ?nm }
  OPTIONAL { ?person pulse:orcidIdentifier ?orc }
  OPTIONAL { ?person pulse:owns ?repo }
} GROUP BY ?person ORDER BY DESC(?repos) LIMIT 40

SELECT ?direction ?property ?value WHERE {
  { <https://github.com/sdsc-ordes/gimie> ?property ?value BIND("out" AS ?direction) }
  UNION
  { ?value ?property <https://github.com/sdsc-ordes/gimie> BIND("in" AS ?direction) }
} ORDER BY DESC(?direction) ?property

