PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?name (SAMPLE(?in) AS ?institution) (SAMPLE(?oh) AS ?organization)
       (SAMPLE(?c) AS ?commits) (SAMPLE(?st) AS ?stars) (SAMPLE(?fk) AS ?forks)
       (SAMPLE(?lic) AS ?license) WHERE {
  ?repo a schema:SoftwareSourceCode ; schema:name ?name ; ossb:numCommits ?c ;
        pulse:githubRepoStars ?st ; pulse:githubRepoForks ?fk .
  OPTIONAL { ?repo ossb:attributedToInstitution ?i . ?i schema:name ?in }
  OPTIONAL { ?repo pulse:ownedBy ?o . ?o pulse:githubOrganizationHandle ?oh }
  OPTIONAL { ?repo gme:license_name ?lic }
} GROUP BY ?repo ?name ORDER BY DESC(?commits) LIMIT 30

PREFIX ossb: <https://w3id.org/rete/oss-benchmark#>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
PREFIX gme: <https://openpulse.science/git-metadata-extractor#>
PREFIX org: <http://www.w3.org/ns/org#>
PREFIX schema: <http://schema.org/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?name ?login ?company ?followers ?publicRepos WHERE {
  ?p a schema:Person ; pulse:githubUsername ?login ; gme:followers_count ?followers .
  OPTIONAL { ?p schema:name ?name } OPTIONAL { ?p gme:company ?company }
  OPTIONAL { ?p gme:public_repos ?publicRepos }
} ORDER BY DESC(?followers) LIMIT 30

PREFIX ossb: <https://w3id.org/rete/oss-benchmark#>
PREFIX pulse: <https://open-pulse.epfl.ch/ontology#>
PREFIX gme: <https://openpulse.science/git-metadata-extractor#>
PREFIX org: <http://www.w3.org/ns/org#>
PREFIX schema: <http://schema.org/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?sector (COUNT(DISTINCT ?repo) AS ?repos) (COUNT(DISTINCT ?lr) AS ?licensed)
       (COUNT(DISTINCT ?pr) AS ?permissive) (COUNT(DISTINCT ?cr) AS ?copyleft) WHERE {
  ?i a ossb:Institution ; ossb:sector ?s . ?s skos:prefLabel ?sector .
  ?o org:unitOf ?i . ?repo pulse:ownedBy ?o ; ossb:isFork false .
  OPTIONAL { ?repo schema:license ?anyl . BIND(?repo AS ?lr) }
  OPTIONAL { ?repo schema:license ?pl . FILTER(?pl IN (<https://spdx.org/licenses/MIT>,<https://spdx.org/licenses/Apache-2.0>,<https://spdx.org/licenses/BSD-3-Clause>,<https://spdx.org/licenses/ISC>)) BIND(?repo AS ?pr) }
  OPTIONAL { ?repo schema:license ?cl . FILTER(?cl IN (<https://spdx.org/licenses/GPL-3.0-only>,<https://spdx.org/licenses/AGPL-3.0-only>,<https://spdx.org/licenses/GPL-2.0-only>,<https://spdx.org/licenses/LGPL-3.0-only>)) BIND(?repo AS ?cr) }
} GROUP BY ?sector ORDER BY DESC(?repos)

