  ?e cg:hasCause ?c ; cg:hasEffect ?f ; cg:hasConfidence ?confidence ; cg:hasTimeLag ?timeLag .
  ?c rdfs:label ?cause . ?f rdfs:label ?effect .
} ORDER BY DESC(?confidence)

PREFIX cg: <http://iwu.fraunhofer.de/causalgraph#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?link ?assertedBy WHERE {
  ?e cg:hasCreator ?cr ; rdfs:label ?link .
  ?cr rdfs:label ?assertedBy .
} ORDER BY ?assertedBy

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?class ?definition WHERE {
  ?c a owl:Class ; rdfs:label ?class .
  OPTIONAL { ?c rdfs:comment ?definition }
} ORDER BY ?class

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?subclass ?superclass WHERE {
  ?a rdfs:subClassOf ?b . ?a rdfs:label ?subclass . ?b rdfs:label ?superclass .
} ORDER BY ?superclass ?subclass

PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?module (COUNT(?c) AS ?classes) WHERE {
  ?c a owl:Class .
  FILTER(STRSTARTS(STR(?c), "http://www.irisa.fr"))
  BIND(REPLACE(STR(?c), "^.*/([a-z-]+)-owl-lite.*$", "$1") AS ?module)
} GROUP BY ?module ORDER BY DESC(?classes)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?concept ?definition WHERE {
  ?concept a owl:Class ; rdfs:comment ?definition .
  FILTER(CONTAINS(STR(?concept), "mr-sequence") || CONTAINS(STR(?concept), "mr-protocol"))
} ORDER BY ?concept

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?property ?domain ?range WHERE {
  ?property a owl:ObjectProperty ; rdfs:domain ?domain ; rdfs:range ?range .
} ORDER BY ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT { ?c rdfs:subClassOf ?parent }
WHERE {
  ?c rdfs:subClassOf ?parent .
  FILTER(CONTAINS(STR(?c), "dataset-processing") && CONTAINS(STR(?parent), "dataset-processing"))
} LIMIT 60

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT ?item ?label WHERE {
  ?item a owl:Class ; rdfs:label ?label .
  FILTER(CONTAINS(STR(?item), "BDI-II"))
} ORDER BY ?label

PREFIX ncit: <http://ncitt.ncit.nih.gov/>
SELECT ?diagnosis (COUNT(?s) AS ?subjects) WHERE {
  ?s ncit:diagnosis ?diagnosis .
} GROUP BY ?diagnosis ORDER BY DESC(?subjects)

PREFIX ncit: <http://ncitt.ncit.nih.gov/>
