examples.sparql:
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?manuscript ?iiif WHERE {
  ?m wdt:P6108 ?iiif ; rdfs:label ?manuscript .
} LIMIT 30

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?place (COUNT(?m) AS ?manuscripts) WHERE {
  ?m wdt:P1071 ?p . ?p rdfs:label ?place .
} GROUP BY ?place ORDER BY DESC(?manuscripts)

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?person ?wikidata WHERE {
  ?p owl:sameAs ?wikidata ; rdfs:label ?person .
} ORDER BY ?person

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ?person ?born ?died WHERE {
  ?p owl:sameAs ?wd ; rdfs:label ?person .
  SERVICE <https://query.wikidata.org/sparql> {
    VALUES ?wd { <http://www.wikidata.org/entity/Q166876> <http://www.wikidata.org/entity/Q184500> <http://www.wikidata.org/entity/Q2609522> }
    ?wd wdt:P569 ?born .
    OPTIONAL { ?wd wdt:P570 ?died }
  }
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?manuscript ?date WHERE {
  ?m wdt:P571 ?date ; rdfs:label ?manuscript .
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?manuscript ?height ?width WHERE {
  ?m wdt:P2048 ?height ; wdt:P2049 ?width ; rdfs:label ?manuscript .
} ORDER BY DESC(?height) LIMIT 25

PREFIX mira: <https://mira.ie/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?manuscript ?script ?contents WHERE {
  ?m mira:contents ?contents ; rdfs:label ?manuscript .
  OPTIONAL { ?m mira:script ?script }
  FILTER(CONTAINS(LCASE(STR(?contents)), "gospel"))
}

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?class (COUNT(?s) AS ?n) WHERE {
  ?s wdt:P31 ?t . OPTIONAL { ?t rdfs:label ?class }
} GROUP BY ?class ORDER BY DESC(?n)

PREFIX mira: <https://mira.ie/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?criterion (COUNT(?m) AS ?manuscripts) WHERE {
  ?m mira:category ?c . ?c rdfs:label ?criterion .
} GROUP BY ?criterion ORDER BY DESC(?manuscripts)

PREFIX mira: <https://mira.ie/prop/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?manuscript ?iiif WHERE {
  ?m mira:category <https://mira.ie/entity/category/vern> ; rdfs:label ?manuscript .
  OPTIONAL { ?m wdt:P6108 ?iiif }
}

PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
SELECT ?collection (COUNT(*) AS ?specimens) WHERE {
  ?s dwc:collectionCode ?collection .
} GROUP BY ?collection ORDER BY DESC(?specimens)

PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX p: <https://bioexplora.cat/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?species ?collector ?photo WHERE {
  ?s dwc:scientificName ?species ; p:preview ?photo .
  OPTIONAL { ?s p:collectedBy ?c . ?c rdfs:label ?collector }
} LIMIT 40

PREFIX p: <https://bioexplora.cat/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?collector (COUNT(?s) AS ?specimens) WHERE {
  ?s p:collectedBy ?c . ?c rdfs:label ?collector .
} GROUP BY ?collector ORDER BY DESC(?specimens) LIMIT 20

PREFIX p: <https://bioexplora.cat/prop/>
PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?species ?family ?place ?photo WHERE {
  ?c rdfs:label "Gasull i Martínez, Lluís" .
  ?s p:collectedBy ?c ; dwc:scientificName ?species .
  OPTIONAL { ?s p:taxon ?sp . ?sp p:parentTaxon+ ?f . ?f p:rank "family" ; rdfs:label ?family }
  OPTIONAL { ?s p:foundIn ?pl . ?pl rdfs:label ?place }
  OPTIONAL { ?s p:preview ?photo }
} LIMIT 30

PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?species ?point WHERE {
  ?s dwc:scientificName ?species ; geo:asWKT ?point .
} LIMIT 3000

PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
SELECT ?species ?type ?cat WHERE {
  ?s dwc:typeStatus ?type ; dwc:scientificName ?species ; dwc:catalogNumber ?cat .
} LIMIT 40

PREFIX class: <https://bioexplora.cat/class/>
PREFIX p: <https://bioexplora.cat/prop/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?model ?mesh WHERE {
  ?m a class:Model3D ; rdfs:label ?model ; p:mesh ?mesh .
} LIMIT 40

PREFIX class: <https://bioexplora.cat/class/>
PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX p: <https://bioexplora.cat/prop/>
SELECT ?species ?common ?country ?recordist ?audio WHERE {
  ?r a class:Recording ; dwc:scientificName ?species ; p:audio ?audio .
  OPTIONAL { ?r dwc:vernacularName ?common }
  OPTIONAL { ?r dwc:country ?country }
  OPTIONAL { ?r dwc:recordedBy ?recordist }
} LIMIT 40

PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
SELECT ?species ?cat ?locality WHERE {
  ?s dwc:family "Cerambycidae" ; dwc:scientificName ?species ; dwc:catalogNumber ?cat .
  OPTIONAL { ?s dwc:locality ?locality }
} LIMIT 40

PREFIX tci: <https://data.graphplaza.com/tree-city-inventory/ns#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?wkt ?species ?h WHERE {
  ?t a tci:Tree ; tci:taxon ?tx ; geo:hasGeometry/geo:asWKT ?wkt .
  ?tx skos:prefLabel ?species .
  FILTER(CONTAINS(?species, "Sequoiadendron"))
  OPTIONAL { ?t tci:heightM ?h }
}
LIMIT 300

PREFIX tci: <https://data.graphplaza.com/tree-city-inventory/ns#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?species ?h ?crown ?muni WHERE {
  ?t a tci:Tree ; tci:heightM ?h ; tci:taxon ?tx ; tci:inMunicipality ?m .
  ?tx skos:prefLabel ?species .
  ?m rdfs:label ?muni .
  OPTIONAL { ?t tci:crownDiameterM ?crown }
}
ORDER BY DESC(?h) LIMIT 25

PREFIX g: <https://w3id.org/rete/geoadmin/prop/>
PREFIX schema: <http://schema.org/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?country ?capital WHERE {
  ?c g:iso ?code ; schema:name ?country .
  SERVICE <https://query.wikidata.org/sparql> {
    ?wd wdt:P297 ?code ; wdt:P36 ?cap .
    ?cap rdfs:label ?capital . FILTER(LANG(?capital) = "en")
  }
} ORDER BY ?country LIMIT 30

PREFIX g: <https://w3id.org/rete/geoadmin/prop/>
PREFIX schema: <http://schema.org/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?c ?country ?boundary WHERE {
  ?c g:iso "ES" ; schema:name ?country ; geo:asWKT ?boundary .
