PREFIX g: <https://geoadmin.rete/prop/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX class: <https://geoadmin.rete/class/>
SELECT ?country ?iso ?boundary WHERE {
  ?c a class:Country ; g:name ?country ; g:iso ?iso ; geo:asWKT ?boundary .
} LIMIT 100

