PREFIX anat: <https://w3id.org/rete/anatomy#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?system (COUNT(?s) AS ?structures) ?model WHERE {
  ?s anat:inSystem ?sys ; anat:glbFile ?model .
  ?sys rdfs:label ?system .
} GROUP BY ?system ?model ORDER BY DESC(?structures)

PREFIX anat: <https://w3id.org/rete/anatomy#>
PREFIX geo3: <https://w3id.org/rete/geo3#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?relation ?neighbour WHERE {
  ?k rdfs:label "Kidney"@en ; anat:side "left" .
  { ?k anat:tissueContinuousWith ?n . BIND("same tissue" AS ?relation) }
  UNION
  { ?k geo3:thermallyCoupledWith ?n . BIND("heat" AS ?relation) }
  ?n rdfs:label ?neighbour . FILTER(langMatches(lang(?neighbour), "en"))
} ORDER BY ?relation LIMIT 20

PREFIX anat: <https://w3id.org/rete/anatomy#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?kind ?term ?icd10 WHERE {
  ?organ rdfs:label "Liver"@en .
  { ?organ anat:relatedDisease ?t . BIND("disease (DOID)" AS ?kind) }
  UNION
  { ?organ anat:relatedPhenotype ?t . BIND("phenotype (HP)" AS ?kind) }
  ?t rdfs:label ?term . FILTER(langMatches(lang(?term), "en"))
  OPTIONAL { ?t anat:icd10 ?icd10 }
} ORDER BY ?kind ?icd10 LIMIT 25

PREFIX anat: <https://w3id.org/rete/anatomy#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT { ?heart anat:hasPart ?p . ?heart rdfs:label ?hl . ?p rdfs:label ?pl . }
WHERE {
  ?heart rdfs:label "Heart"@en , ?hl . ?heart anat:hasPart ?p . ?p rdfs:label ?pl .
  FILTER(langMatches(lang(?hl),"en") && langMatches(lang(?pl),"en"))
}

