  ?s a bot:Storey ; rdfs:label ?floor ; cad:glbModel ?model .
} ORDER BY ?floor

PREFIX bot: <https://w3id.org/bot#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?floor ?room WHERE {
  ?s a bot:Storey ; rdfs:label ?floor ; bot:hasSpace ?r .
  ?r rdfs:label ?room .
} ORDER BY ?floor ?room

PREFIX bot: <https://w3id.org/bot#>
PREFIX cad: <https://w3id.org/rete/cad#>
SELECT ?type (COUNT(?e) AS ?count) WHERE {
  ?e a bot:Element ; cad:ifcClass ?type .
} GROUP BY ?type ORDER BY DESC(?count)

PREFIX cad: <https://w3id.org/rete/cad#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?neighbour WHERE {
  ?w rdfs:label "Wohnen"@en ; cad:adjacentSpace ?n .
  ?n rdfs:label ?neighbour .
}

PREFIX cad: <https://w3id.org/rete/cad#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?wall WHERE {
  ?k rdfs:label "Küche"@en .
  ?e cad:boundsSpace ?k ; cad:ifcClass "IfcWallStandardCase" ; rdfs:label ?wall .
}

PREFIX cad: <https://w3id.org/rete/cad#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT { ?k cad:enclosedBy ?e . ?k rdfs:label ?room . ?e rdfs:label ?wall . }
WHERE {
  ?k rdfs:label "Küche"@en , ?room .
  ?e cad:boundsSpace ?k ; cad:ifcClass "IfcWallStandardCase" ; rdfs:label ?wall .
}

PREFIX g: <https://w3id.org/rete/gnibim#>
SELECT ?subset ?discipline (COUNT(?m) AS ?models) WHERE {
  ?m a g:Model ; g:subset ?subset ; g:discipline ?discipline .
} GROUP BY ?subset ?discipline ORDER BY DESC(?models)

PREFIX g: <https://w3id.org/rete/gnibim#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?ifcClass (SUM(?c) AS ?instances) WHERE {
  ?t g:ifcClass ?cl ; g:count ?c . ?cl rdfs:label ?ifcClass .
} GROUP BY ?ifcClass ORDER BY DESC(?instances)

PREFIX g: <https://w3id.org/rete/gnibim#>
SELECT (COUNT(?m) AS ?models) (MIN(?e) AS ?minElements) (ROUND(AVG(?e)) AS ?meanElements) (MAX(?e) AS ?maxElements) WHERE {
  ?m g:subset "fundamentals" ; g:elementCount ?e .
