}

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?text ?language WHERE {
  <http://ldf.fi/mmm/manifestation_singleton/sdbm_orphan_212926> crm:P128_carries ?expr .
  ?expr skos:prefLabel ?text ; crm:P72_has_language/skos:prefLabel ?language .
}

PREFIX crm: <http://erlangen-crm.org/current/>
PREFIX mmm: <http://ldf.fi/schema/mmm/>
