SELECT ?title (COUNT(?earlier) AS ?position) ?family ?given ?agent WHERE {
  ?work oc:doiLink <https://doi.org/10.17640/kswst.2016.24.6.137> ; dcterms:title ?title ;
        pro:isDocumentContextFor ?role , ?earlier .
  ?role pro:withRole pro:author ; pro:isHeldBy ?agent .
  ?earlier pro:withRole pro:author ; oco:hasNext* ?role .
  OPTIONAL { ?agent foaf:familyName ?family }
  OPTIONAL { ?agent foaf:givenName ?given }
} GROUP BY ?title ?role ?family ?given ?agent ORDER BY ?position

