            prov:atLocation ?source .
} GROUP BY ?source ORDER BY DESC(?citations)

PREFIX cito: <http://purl.org/spar/cito/>
SELECT ?citation ?cited ?kind WHERE {
  ?citation cito:hasCitingEntity <https://w3id.org/oc/meta/br/0601785> ;
            cito:hasCitedEntity ?cited ;
            a ?kind .
  FILTER(?kind IN (cito:JournalSelfCitation, cito:AuthorSelfCitation))
} ORDER BY ?kind ?cited

PREFIX cito: <http://purl.org/spar/cito/>
SELECT ?count (COUNT(?citation) AS ?citations) WHERE {
  { ?citation cito:hasCitingEntity <https://w3id.org/oc/meta/br/0601785> . BIND("references made" AS ?count) }
  UNION { ?citation cito:hasCitedEntity <https://w3id.org/oc/meta/br/0601785> . BIND("citations received" AS ?count) }
  UNION { ?citation cito:hasCitingEntity <https://w3id.org/oc/meta/br/0601785> ; a cito:JournalSelfCitation .
          BIND("journal self-citations" AS ?count) }
  UNION { ?citation cito:hasCitingEntity <https://w3id.org/oc/meta/br/0601785> ; a cito:AuthorSelfCitation .
          BIND("author self-citations" AS ?count) }
} GROUP BY ?count ORDER BY ?count

