  ?pl a mb:Placement ; mb:mature ?m ; mb:stemLoop ?h ;
      mb:matureFrom ?from ; mb:matureTo ?to .
  ?m rdfs:label ?mature .
  ?h rdfs:label ?stemLoop .
  FILTER(STRSTARTS(?mature, "oan-miR-153"))
