shacl_shapes.shape:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix vs: <https://scrollprize.org/vocab#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix dct: <http://purl.org/dc/terms/> .
@prefix shp: <https://scrollprize.org/shapes#> .

shp:DataAssetShape a sh:NodeShape ;
    sh:targetClass vs:DataAsset ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] ;
    sh:property [
        sh:path vs:assetType ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] ;
    sh:property [
        sh:path vs:assetOf ;
        sh:minCount 1 ;
        sh:or ( [ sh:class vs:Segment ] [ sh:class vs:Volume ] ) ;
    ] ;
    sh:property [
        sh:path vs:targetVolume ;
        sh:class vs:Volume ;
    ] ;
    sh:property [
        sh:path vs:usedModel ;
        sh:class vs:Model ;
    ] ;
    sh:property [
        sh:path dct:created ;
        sh:nodeKind sh:Literal ;
    ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix vs: <https://scrollprize.org/vocab#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix dct: <http://purl.org/dc/terms/> .
@prefix shp: <https://scrollprize.org/shapes#> .

shp:SegmentShape a sh:NodeShape ;
    sh:targetClass vs:Segment ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] ;
    sh:property [
        sh:path dct:created ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] ;
    sh:property [
        sh:path vs:bbox ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] ;
    sh:property [
        sh:path vs:widthPx ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] ;
    sh:property [
        sh:path vs:heightPx ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] ;
    sh:property [
        sh:path vs:fromVolume ;
        sh:minCount 1 ;
        sh:class vs:Volume ;
    ] ;
    sh:property [
        sh:path vs:sample ;
        sh:class vs:Scroll ;
    ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix vs: <https://scrollprize.org/vocab#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix shp: <https://scrollprize.org/shapes#> .

shp:VolumeShape a sh:NodeShape ;
    sh:targetClass vs:Volume ;
    sh:property [
        sh:path rdfs:label ;
        sh:minCount 1 ;
        sh:nodeKind sh:Literal ;
    ] .

examples.sparql:
PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT ?title ?loc ?call ?avail WHERE {
  ?lib schema:name "Archives cantonales" .
  ?it b:heldAt ?lib ;
      schema:name ?title ;
      b:shelvingLocation ?loc ;
      b:callNumber ?call ;
      b:availability ?avail .
} LIMIT 100

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT ?section (COUNT(?it) AS ?items) WHERE {
  ?lib schema:name "BCUL site Unithèque" .
  ?it b:heldAt ?lib ;
      b:shelvingLocation ?section .
} GROUP BY ?section ORDER BY DESC(?items) LIMIT 25

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT ?call ?title ?date WHERE {
  ?it b:callNumber ?call ;
      schema:name ?title .
  FILTER(STRSTARTS(?call, "USA 108"))
  OPTIONAL { ?it schema:startDate ?date }
} ORDER BY ?call LIMIT 60

