PREFIX b: <https://data.bcu-lausanne.ch/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?thumb ?title ?date ?place ?lang ?manifest WHERE {
  ?m a schema:Manuscript ;
     schema:thumbnailUrl ?thumb ;
     schema:name ?title ;
     schema:startDate ?date ;
     b:iiifManifest ?manifest .
  OPTIONAL { ?m schema:spatialCoverage ?pl . ?pl schema:name ?place }
  OPTIONAL { ?m schema:inLanguage ?lg . ?lg rdfs:label ?lang }
} ORDER BY ?date

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT ?thumb ?title ?creator ?date ?url WHERE {
  ?it schema:isPartOf <https://data.bcu-lausanne.ch/source/patrinum> ;
      schema:image ?thumb ;
      schema:name ?title ;
      schema:url ?url ;
      schema:startDate ?date .
  OPTIONAL { ?it schema:creator ?a . ?a schema:name ?creator }
} ORDER BY ?date LIMIT 60

PREFIX schema: <http://schema.org/>
SELECT ?title ?author ?date ?pdf WHERE {
  ?it schema:associatedMedia ?pdf ;
      schema:name ?title ;
      schema:startDate ?date .
  FILTER(STRSTARTS(STR(?pdf), "https://patrinum.ch/record/"))
  OPTIONAL { ?it schema:creator ?a . ?a schema:name ?author }
} ORDER BY ?date LIMIT 60

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT ?manifest ?title ?date ?pdf WHERE {
  ?it b:iiifManifest ?manifest ;
      schema:name ?title ;
      schema:startDate ?date .
  FILTER(STRSTARTS(STR(?manifest), "https://data.graphplaza.com/bcul/iiif/"))
  OPTIONAL { ?it schema:associatedMedia ?pdf }
} ORDER BY ?date LIMIT 60

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?title ?date ?lib WHERE {
  ?w a schema:Book ;
     schema:name ?title ;
     schema:startDate ?date ;
     b:heldAt ?h .
  ?h schema:name ?lib .
  FILTER(?date > "1450"^^xsd:gYear)
} ORDER BY ?date LIMIT 50

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT ?name (COUNT(?w) AS ?n) WHERE {
  ?w schema:creator ?a .
  ?a schema:name ?name .
} GROUP BY ?name ORDER BY DESC(?n) LIMIT 25

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT ?library (COUNT(?it) AS ?items) WHERE {
  ?it b:heldAt ?lib .
  ?lib schema:name ?library .
} GROUP BY ?library ORDER BY DESC(?items) LIMIT 25

PREFIX schema: <http://schema.org/>
SELECT DISTINCT ?title WHERE {
  ?s schema:isPartOf <https://data.bcu-lausanne.ch/source/scriptorium> ;
     a schema:Periodical ;
     schema:name ?title .
} LIMIT 60

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
SELECT DISTINCT ?call ?neighbour WHERE {
  ?anchor schema:name "Foundations for moral relativism" ;
          b:callNumber ?c0 ; b:heldAt ?lib .
  ?it b:heldAt ?lib ;
      b:callNumber ?call ;
      schema:name ?neighbour .
  FILTER(?call >= ?c0)
} ORDER BY ?call LIMIT 25

PREFIX schema: <http://schema.org/>
PREFIX b: <https://data.bcu-lausanne.ch/>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?thumb ?manifest ?title ?century ?year ?record WHERE {
  ?w b:iiifManifest ?manifest ;
     schema:thumbnailUrl ?thumb ;
     schema:name ?title ;
     schema:url ?record .
  OPTIONAL { ?w dct:date ?century }
  OPTIONAL { ?w schema:startDate ?year }
} ORDER BY ?year

