PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
SELECT ?lang ?name WHERE {
  <https://w3id.org/rete/gbif/taxon/species/9515886> dwc:vernacularName ?name .
  BIND(LANG(?name) AS ?lang)
}
ORDER BY ?lang

PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?sp ?n ?sci WHERE {
  ?sp dwc:vernacularName ?n ; rdfs:label ?sci .
  FILTER(LANG(?n) = "ca" && CONTAINS(LCASE(STR(?n)), "oreneta"))
}

PREFIX v: <https://w3id.org/rete/gbif/vocab#>
PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?status ?name ?sci WHERE {
  ?sp v:sensitive true ; v:iucnStatus ?status ; rdfs:label ?sci .
  OPTIONAL { ?sp dwc:vernacularName ?name . FILTER(LANG(?name) = "en") }
}
ORDER BY DESC(?status)

PREFIX v: <https://w3id.org/rete/gbif/vocab#>
SELECT ?rc ?est ?fy ?ly WHERE {
  <https://w3id.org/rete/gbif/taxon/species/2481912> v:recordCount ?rc ; v:firstYear ?fy ; v:lastYear ?ly .
  OPTIONAL { <https://w3id.org/rete/gbif/taxon/species/2481912> v:estimatedIndividuals ?est }
}

