PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX sc: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?num ?pos ?player ?club ?dob WHERE {
  <https://w3id.org/rete/worldcup/team/Argentina> wc:squadPlayer ?p .
  ?p sc:name ?player .
  OPTIONAL { ?p wc:shirtNumber ?num }
  OPTIONAL { ?p wc:position ?pos }
  OPTIONAL { ?p sc:birthDate ?dob }
  OPTIONAL { ?p wc:clubAtTournament ?c . ?c rdfs:label ?club }
} ORDER BY xsd:integer(?num)

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?club (COUNT(?p) AS ?players) WHERE {
  ?p wc:clubAtTournament ?c .
  ?c rdfs:label ?club .
} GROUP BY ?club ORDER BY DESC(?players) LIMIT 20

PREFIX wc: <https://w3id.org/rete/worldcup#>
SELECT ?kind (COUNT(?s) AS ?n) WHERE {
  ?s a ?c .
  VALUES ?c { wc:Match wc:Goal wc:Stadium wc:Prediction wc:CareerStint }
  BIND(STRAFTER(STR(?c), "#") AS ?kind)
} GROUP BY ?kind ORDER BY DESC(?n)

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX sc: <http://schema.org/>
SELECT ?player (COUNT(?g) AS ?goals) WHERE {
  ?g a wc:Goal ; wc:scoredBy ?p .
  ?p sc:name ?player .
  FILTER NOT EXISTS { ?g wc:ownGoal true }
} GROUP BY ?player ORDER BY DESC(?goals) LIMIT 15

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?date ?prob WHERE {
  ?pr wc:aboutTeam <https://w3id.org/rete/worldcup/team/Argentina> ;
      wc:outcome wc:Champion ;
      wc:probability ?prob ;
      wc:forecastDate ?date ;
      prov:wasAttributedTo <https://w3id.org/rete/worldcup/source/538> .
} ORDER BY ?date

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX sc: <http://schema.org/>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?team ?src ?prob WHERE {
  ?pr wc:outcome wc:Champion ;
      wc:forecastDate "2022-11-20"^^xsd:date ;
      wc:aboutTeam ?t ; wc:probability ?prob ;
      prov:wasAttributedTo ?s .
  ?t sc:name ?team .
  ?s sc:name ?src .
} ORDER BY DESC(?prob) LIMIT 18

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX sc: <http://schema.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?scorer ?min ?team WHERE {
  ?g wc:inMatch <https://w3id.org/rete/worldcup/match/064> ;
     wc:scoredBy ?p ; wc:minute ?min ; wc:forTeam ?tm .
  ?p sc:name ?scorer .
  ?tm sc:name ?team .
} ORDER BY xsd:integer(?min)

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX sc: <http://schema.org/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?club ?from ?to WHERE {
  ?st a wc:CareerStint ;
      wc:player <https://w3id.org/rete/worldcup/player/Lionel_Messi> ;
      wc:club ?c .
  ?c rdfs:label ?club .
  OPTIONAL { ?st sc:startDate ?from }
  OPTIONAL { ?st sc:endDate ?to }
} ORDER BY ?from

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX sc: <http://schema.org/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?name ?cap ?wkt WHERE {
  ?s a wc:Stadium ; sc:name ?name ; geo:asWKT ?wkt .
  OPTIONAL { ?s wc:capacity ?cap }
} ORDER BY DESC(?cap)

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sc: <http://schema.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?stage ?match ?when WHERE {
  ?m a wc:Match ; wc:stage ?stage ; rdfs:label ?match .
  OPTIONAL { ?m sc:startDate ?when }
  FILTER(?stage != "group")
} ORDER BY ?when

PREFIX wc: <https://w3id.org/rete/worldcup#>
PREFIX sc: <http://schema.org/>
PREFIX prov: <http://www.w3.org/ns/prov#>
SELECT ?date ?team ?prob WHERE {
  ?pr wc:outcome wc:Champion ;
      prov:wasAttributedTo <https://w3id.org/rete/worldcup/source/538> ;
      wc:aboutTeam ?t ; wc:probability ?prob ; wc:forecastDate ?date .
  ?t sc:name ?team .
  FILTER(?prob > 0.10)
} ORDER BY ?date DESC(?prob)

