SELECT ?performance ?skill ?animation WHERE {
  ?perf dance:animation ?animation ; rdfs:label ?performance ;
        dance:hasLeader/dance:hasSkillLevel/rdfs:label ?skill .
} ORDER BY ?performance

PREFIX dance: <https://w3id.org/rete/dance#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?couple ?skill (COUNT(?seg) AS ?moves) (ROUND(AVG(?hcf)*1000)/1000 AS ?handContact) (ROUND(AVG(?sep)*100)/100 AS ?separation_m) ?animation WHERE {
  ?perf dance:animation ?animation ; rdfs:label ?couple ;
        dance:hasLeader/dance:hasSkillLevel/rdfs:label ?skill ;
        dance:hasSegment ?seg .
  ?seg dance:handContactFraction ?hcf ; dance:meanCoupleSeparation ?sep .
} GROUP BY ?perf ?couple ?skill ?animation ORDER BY DESC(?handContact)

PREFIX dance: <https://w3id.org/rete/dance#>
SELECT ?metric ?n WHERE {
  { SELECT ("dancers" AS ?metric) (COUNT(?d) AS ?n) WHERE { ?d a dance:Dancer } }
  UNION { SELECT ("pairs" AS ?metric) (COUNT(?p) AS ?n) WHERE { ?p a dance:Pair } }
  UNION { SELECT ("performances" AS ?metric) (COUNT(?pf) AS ?n) WHERE { ?pf a dance:Performance } }
  UNION { SELECT ("move segments" AS ?metric) (COUNT(?s) AS ?n) WHERE { ?x dance:hasSegment ?s } }
}

