PREFIX ror: <https://w3id.org/rete/ror#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?org ?name ?city ?est ?website WHERE {
  ?org ror:countryCode "CH" ;
       rdfs:label ?name ;
       ror:locationName ?city ;
       ror:established ?est ;
       ror:website ?website .
} ORDER BY ?est LIMIT 200

PREFIX ror: <https://w3id.org/rete/ror#>
SELECT ?country ?type (COUNT(?org) AS ?orgs) WHERE {
  ?org ror:countryName ?country ;
       a ?type .
  FILTER(?type != ror:Organization)
} GROUP BY ?country ?type ORDER BY DESC(?orgs) LIMIT 40

PREFIX ror: <https://w3id.org/rete/ror#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?c ?name ?city ?lat ?long WHERE {
  <https://ror.org/02feahw73> ror:hasChild ?c .
  ?c rdfs:label ?name ;
     ror:locationName ?city ;
     ror:lat ?lat ;
     ror:long ?long .
} ORDER BY ?name LIMIT 400

PREFIX orc: <https://w3id.org/rete/orcid#>
PREFIX ror: <https://w3id.org/rete/ror#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?orgName ?city ?person ?name ?role ?start WHERE {
  <https://ror.org/02s376052> ror:name ?orgName ;
       ror:locationName ?city .
  ?a orc:affiliationWith <https://ror.org/02s376052> ;
     orc:affiliationOf ?person ;
     orc:roleTitle ?role ;
     orc:startYear ?start .
  ?person rdfs:label ?name .
} LIMIT 50

shacl_shapes.shape:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ror: <https://w3id.org/rete/ror#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

ror:OrganizationShape a sh:NodeShape ;
  sh:targetClass ror:Organization ;
  sh:property [
    sh:path ror:rorId ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
    sh:maxCount 1 ;
  ] ;
  sh:property [
    sh:path rdfs:label ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
  ] ;
  sh:property [
    sh:path ror:name ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
  ] ;
  sh:property [
    sh:path ror:countryCode ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
    sh:maxCount 1 ;
  ] ;
  sh:property [
    sh:path ror:countryName ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
  ] ;
  sh:property [
    sh:path ror:locationName ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
  ] ;
  sh:property [
    sh:path ror:lat ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
    sh:maxCount 1 ;
  ] ;
  sh:property [
    sh:path ror:long ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
    sh:maxCount 1 ;
  ] ;
  sh:property [
    sh:path ror:status ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
    sh:maxCount 1 ;
  ] ;
  sh:property [
    sh:path ror:website ;
    sh:nodeKind sh:Literal ;
  ] ;
  sh:property [
    sh:path ror:grid ;
    sh:nodeKind sh:Literal ;
  ] ;
  sh:property [
    sh:path ror:established ;
    sh:nodeKind sh:Literal ;
  ] .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix ror: <https://w3id.org/rete/ror#> .

ror:OrganizationTypeShape a sh:NodeShape ;
  sh:targetClass ror:Organization ;
  sh:or (
    [ sh:path rdf:type ; sh:hasValue ror:Company ]
    [ sh:path rdf:type ; sh:hasValue ror:Education ]
    [ sh:path rdf:type ; sh:hasValue ror:Funder ]
    [ sh:path rdf:type ; sh:hasValue ror:Nonprofit ]
    [ sh:path rdf:type ; sh:hasValue ror:Healthcare ]
    [ sh:path rdf:type ; sh:hasValue ror:Facility ]
    [ sh:path rdf:type ; sh:hasValue ror:OtherOrganization ]
    [ sh:path rdf:type ; sh:hasValue ror:Government ]
    [ sh:path rdf:type ; sh:hasValue ror:Archive ]
  ) .

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix ror: <https://w3id.org/rete/ror#> .

ror:OrganizationHierarchyShape a sh:NodeShape ;
  sh:targetClass ror:Organization ;
  sh:property [
    sh:path ror:hasParent ;
    sh:class ror:Organization ;
    sh:nodeKind sh:IRI ;
  ] .

examples.sparql:
PREFIX dblp: <https://w3id.org/rete/dblp#>
SELECT ?p ?title ?venue ?year WHERE {
  ?p dblp:authoredBy <https://orcid.org/0000-0003-4827-1793> ;
     dblp:title ?title ; dblp:venue ?venue ; dblp:year ?year .
} ORDER BY DESC(?year) LIMIT 50

PREFIX dblp: <https://w3id.org/rete/dblp#>
SELECT ?name ?coauthor (COUNT(?p) AS ?shared) WHERE {
  ?p dblp:authoredBy <https://orcid.org/0000-0003-4827-1793> , ?coauthor .
  ?coauthor dblp:creatorName ?name .
  FILTER(?coauthor != <https://orcid.org/0000-0003-4827-1793>)
} GROUP BY ?coauthor ?name ORDER BY DESC(?shared) LIMIT 30

PREFIX dblp: <https://w3id.org/rete/dblp#>
SELECT ?p ?title ?venue ?year WHERE {
  ?p dblp:authoredBy <https://orcid.org/0000-0003-4827-1793> ;
     dblp:doi ?d ; dblp:title ?title ; dblp:venue ?venue ; dblp:year ?year .
} ORDER BY DESC(?year) LIMIT 50

PREFIX dblp: <https://w3id.org/rete/dblp#>
SELECT ?author ?name ?orcid WHERE {
  <https://dblp.org/rec/journals/corr/AfifyEAA16> dblp:authoredBy ?author .
  ?author dblp:creatorName ?name .
  OPTIONAL { ?author dblp:orcid ?orcid }
}

PREFIX dblp: <https://w3id.org/rete/dblp#>
SELECT ?year (COUNT(?p) AS ?papers) WHERE {
  ?p dblp:authoredBy <https://orcid.org/0000-0003-4827-1793> ;
     dblp:year ?year .
} GROUP BY ?year ORDER BY ?year

PREFIX dblp: <https://w3id.org/rete/dblp#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?p dblp:authoredBy ?a .
  ?p rdfs:label ?t .
  ?a rdfs:label ?n .
} WHERE {
  ?p dblp:authoredBy <https://orcid.org/0000-0003-4827-1793> ;
     dblp:authoredBy ?a .
  OPTIONAL { ?p rdfs:label ?t }
  OPTIONAL { ?a rdfs:label ?n }
} LIMIT 80

