examples.sparql:
PREFIX aifx: <https://w3id.org/rete/aif#>
PREFIX schema: <https://schema.org/>
SELECT ?who (COUNT(?l) AS ?utterances) WHERE {
  ?l aifx:speaker ?s .
  ?s schema:name ?who .
} GROUP BY ?who ORDER BY DESC(?utterances) LIMIT 25

PREFIX aif: <http://www.arg.tech/aif#>
PREFIX aifx: <https://w3id.org/rete/aif#>
SELECT ?scheme (COUNT(*) AS ?n) WHERE {
  ?l aifx:speaker <https://w3id.org/rete/aifdb/speaker/Lisa_Nandy> ;
     aifx:edgeTo ?ya .
  ?ya a aif:YA-node ; aifx:scheme ?scheme .
} GROUP BY ?scheme ORDER BY DESC(?n)

PREFIX aif: <http://www.arg.tech/aif#>
PREFIX aifx: <https://w3id.org/rete/aif#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
CONSTRUCT {
  ?a aifx:conflictsWith ?b .
  ?a rdfs:label ?la .
  ?b rdfs:label ?lb .
} WHERE {
  ?a aifx:conflictsWith ?b .
  ?a rdfs:label ?la .
  ?b rdfs:label ?lb .
} LIMIT 40

PREFIX pa: <https://w3id.org/rete/plantatlas/ontology#>
PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX schema: <http://schema.org/>
SELECT ?name ?part ?image WHERE {
  ?photo a pa:Photo ; dwc:genus "Triticum" ;
         dwc:scientificName ?name ; pa:plantPart ?part ;
         schema:image ?image .
} LIMIT 40

PREFIX pa: <https://w3id.org/rete/plantatlas/ontology#>
PREFIX schema: <http://schema.org/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name ?image ?wkt WHERE {
  ?photo a pa:Photo ; pa:source "nature" ; rdfs:label ?name ;
         schema:image ?image ; pa:atLocality ?loc .
  ?loc geo:asWKT ?wkt .
} LIMIT 400

PREFIX pa: <https://w3id.org/rete/plantatlas/ontology#>
PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
SELECT ?family (COUNT(?photo) AS ?n) WHERE {
  ?photo a pa:Photo ; dwc:family ?family .
} GROUP BY ?family ORDER BY DESC(?n) LIMIT 25

PREFIX pa: <https://w3id.org/rete/plantatlas/ontology#>
SELECT ?part (COUNT(?photo) AS ?n) WHERE {
  ?photo a pa:Photo ; pa:plantPart ?part .
} GROUP BY ?part ORDER BY DESC(?n) LIMIT 20

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?doi ?title ?year ?publisher ?type WHERE {
  ?doi dcite:title ?title ;
       dcite:publicationYear ?year ;
       dcite:publisherName ?publisher ;
       dcite:resourceType ?type .
}
LIMIT 25

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?doi ?title ?year ?publisher ?citations WHERE {
  ?doi a dcite:Software ;
       dcite:title ?title ;
       dcite:publicationYear ?year ;
       dcite:publisherName ?publisher ;
       dcite:citationCount ?citations .
}
ORDER BY DESC(?citations) LIMIT 25

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?from ?type ?to ?assertedBy ?title WHERE {
  ?rel a dcite:PidRelation ;
       dcite:relationSubject ?from ;
       dcite:relationType ?type ;
       dcite:relationObject ?to .
  OPTIONAL { ?rel dcite:assertedBy ?assertedBy }
  OPTIONAL { ?from dcite:title ?title }
}
LIMIT 25

PREFIX dcite: <https://w3id.org/rete/datacite#>
PREFIX dct: <http://purl.org/dc/terms/>
SELECT ?type (COUNT(*) AS ?records) WHERE {
  ?s a ?type .
}
GROUP BY ?type ORDER BY DESC(?records)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?record ?relation ?doi ?asWritten WHERE {
  ?r rdf:reifies << ?record ?relation ?doi >> ;
     dcite:relatedIdentifierAsWritten ?asWritten .
}
LIMIT 25

PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?doi ?title WHERE {
  ?doi dcite:title ?title .
  FILTER(CONTAINS(?title, "permafrost"))
}
LIMIT 25

PREFIX epfl: <https://w3id.org/rete/epflgraph#>
SELECT ?concept ?name ?neighbour ?neighbourName ?wikipedia WHERE {
  ?concept epfl:name "Machine learning" ;
           epfl:similarTo ?neighbour .
  ?neighbour epfl:name ?neighbourName .
  OPTIONAL { ?neighbour epfl:referencePageUrl ?wikipedia }
  BIND("Machine learning" AS ?name)
}
LIMIT 25

PREFIX epfl: <https://w3id.org/rete/epflgraph#>
SELECT ?category ?name ?topic ?wikipedia ?depth WHERE {
  ?category epfl:alignedTopic ?topic ;
            epfl:name ?name .
  OPTIONAL { ?category epfl:referencePageUrl ?wikipedia }
  OPTIONAL { ?category epfl:depth ?depth }
}
LIMIT 25

PREFIX epfl: <https://w3id.org/rete/epflgraph#>
SELECT ?child ?childName ?parentName ?wikipedia ?depth WHERE {
  ?child epfl:broader ?parent ;
         epfl:name ?childName .
  ?parent epfl:name ?parentName .
  OPTIONAL { ?child epfl:referencePageUrl ?wikipedia }
  OPTIONAL { ?child epfl:depth ?depth }
}
LIMIT 25

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?doi ?work ?title ?venue ?year ?publisher ?issn WHERE {
  ?work cx:doi ?doi ; rdfs:label ?title ; cx:containerTitle ?venue ;
        cx:issuedYear ?year ; cx:publisherName ?publisher ; cx:issn ?issn .
} LIMIT 25

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?work ?title ?position ?given ?family ?orcid ?authenticated WHERE {
  ?work cx:author ?a ; rdfs:label ?title .
  ?a cx:isHeldBy ?orcid ; cx:position ?position ; cx:familyName ?family .
  OPTIONAL { ?a cx:givenName ?given }
  OPTIONAL { ?a cx:orcidAuthenticated ?authenticated }
} LIMIT 30

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?work ?title ?funderName ?award WHERE {
  ?work cx:funding ?f ; rdfs:label ?title .
  ?f cx:funder <https://doi.org/10.13039/100000002> ; cx:funderName ?funderName ; cx:awardNumber ?award .
} LIMIT 30

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?notice ?retracted ?title ?date ?source WHERE {
  ?u cx:updateType "retraction" ; cx:updatingWork ?notice ;
     cx:updatedWork ?retracted .
  OPTIONAL { ?retracted rdfs:label ?title }
  OPTIONAL { ?u cx:updateDate ?date }
  OPTIONAL { ?u cx:updateSource ?source }
} LIMIT 30

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?preprint ?ptitle ?work ?title WHERE {
  ?preprint cx:isPreprintOf ?work ; rdfs:label ?ptitle .
  ?work rdfs:label ?title .
} LIMIT 25

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?class ?label ?super ?equiv ?comment WHERE {
  ?class a owl:Class .
  OPTIONAL { ?class rdfs:label ?label . }
  OPTIONAL { ?class rdfs:subClassOf ?super . FILTER(isIRI(?super)) }
  OPTIONAL { ?class owl:equivalentClass ?equiv . }
  OPTIONAL { ?class rdfs:comment ?comment . }
} LIMIT 60

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(?citing) AS ?citers) WHERE {
  ?citing cx:cites <https://doi.org/10.1038/nature12373> .
}

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?mid ?far WHERE {
  <https://doi.org/10.1021/ja0113697> cx:cites ?mid .
  ?mid cx:cites ?far .
} LIMIT 50

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?citing ?cited ?text WHERE {
  ?r rdf:reifies << ?citing cx:cites ?cited >> ; cx:citedDOIAsWritten ?text .
} LIMIT 25

PREFIX cx: <https://w3id.org/rete/crossref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?work ?text WHERE {
  ?work cx:citedDOIText ?text .
} LIMIT 25
